using Dapper; using Npgsql; using PlantaoPro.Api.Models;
namespace PlantaoPro.Api.Data;
public sealed class PagamentoContestacaoService(IConfiguration cfg,ICurrentUserService user,IAuditService audit)
{
 private NpgsqlConnection Cn()=>new(cfg.GetConnectionString("Default")); private Guid Tenant=>user.ClienteId??user.TenantId??throw new UnauthorizedAccessException(); private Guid UserId=>user.UserId??throw new UnauthorizedAccessException();
 public async Task<ApiResponse<PagamentoActionResponse>> ResolveAsync(Guid pagamentoId,ResolverContestacaoPagamentoRequest request){var decision=(request.Decisao??"").Trim().ToUpperInvariant();var justification=(request.Justificativa??"").Trim();if(!new[]{"MANTER_VALOR","AJUSTAR_VALOR","CANCELAR_PAGAMENTO"}.Contains(decision)||justification.Length is <5 or >500)return ApiResponse<PagamentoActionResponse>.Fail("Decisão e justificativa válidas são obrigatórias.",422);if(decision=="AJUSTAR_VALOR"&&request.NovoValor is not >0)return ApiResponse<PagamentoActionResponse>.Fail("Novo valor positivo é obrigatório.",422);await using var cn=Cn();await cn.OpenAsync();await using var tx=await cn.BeginTransactionAsync();var pg=await cn.QuerySingleOrDefaultAsync<(Guid Id,string Status,decimal Valor)>("select pg.id Id,pg.status Status,coalesce(pg.valor_previsto,0) Valor from plantaopro.pagamentos pg join plantaopro.plantoes p on p.id=pg.plantao_id where pg.id=@pagamentoId and p.cliente_id=@tenant and pg.reg_status='A' for update",new{pagamentoId,tenant=Tenant},tx);if(pg.Id==Guid.Empty)return ApiResponse<PagamentoActionResponse>.Fail("Pagamento não encontrado.",404);var contest=await cn.ExecuteScalarAsync<Guid?>("select id from plantaopro.pagamento_contestacoes where pagamento_id=@pagamentoId and tenant_id=@tenant and status='ABERTA' for update",new{pagamentoId,tenant=Tenant},tx);if(!contest.HasValue)return ApiResponse<PagamentoActionResponse>.Fail("Contestação aberta não encontrada.",404);var next=decision=="CANCELAR_PAGAMENTO"?"cancelado":"pendente";var value=decision=="AJUSTAR_VALOR"?request.NovoValor!.Value:pg.Valor;var changed=await cn.ExecuteAsync("update plantaopro.pagamentos set status=@next,valor_previsto=@value,observacoes=@justification,updated_by=@user,reg_update=now() where id=@pagamentoId and status='contestado'",new{next,value,justification,user=UserId,pagamentoId},tx);if(changed!=1)return ApiResponse<PagamentoActionResponse>.Fail("Pagamento não está contestado.",409);await cn.ExecuteAsync("update plantaopro.pagamento_contestacoes set status='RESOLVIDA',decisao=@decision,justificativa_resolucao=@justification,valor_resolvido=@value,resolvido_por=@user,resolvido_em=now(),updated_at=now() where id=@id and status='ABERTA'",new{decision,justification,value,user=UserId,id=contest.Value},tx);await cn.ExecuteAsync("insert into plantaopro.historico_pagamento(id,pagamento_id,status_anterior,status_novo,justificativa,usuario_id,reg_date) values(gen_random_uuid(),@pagamentoId,@old,@next,@justification,@user,now())",new{pagamentoId,old=pg.Status,next,justification,user=UserId},tx);await tx.CommitAsync();await audit.RegistrarAsync(UserId,Tenant,"PAGAMENTO_CONTESTACAO",contest.Value,"RESOLVER",new{decision,ValorAnterior=pg.Valor,ValorResolvido=value},true,null,string.Join(',',user.Roles));return ApiResponse<PagamentoActionResponse>.Ok(new PagamentoActionResponse(pagamentoId,next,value,null,"concluido"),"Contestação resolvida.");}
}
